import subprocess
import os
import glob
import time
def task_func(test_dir):
    results = {}
    python_files = glob.glob(os.path.join(test_dir, "*.py"))
    for script in python_files:
        start_time = time.time()
        try:
            subprocess.run(['python', script], stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=True)
        except Exception:
            pass
        end_time = time.time()
        results[os.path.basename(script)] = end_time - start_time
    return results

