import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")
    data = []
    start_time = time.time()
    system = platform.system().lower()
    command = ['wmic', 'cpu', 'get', 'loadpercentage'] if 'windows' in system else ['mpstat', '1', '1']
    while time.time() - start_time < duration:
        try:
            result = subprocess.run(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
            if result.returncode == 0:
                if 'windows' in system:
                    usage = int(result.stdout.splitlines()[1].strip())
                else:
                    usage = 100 - float(result.stdout.splitlines()[-1].split()[-1])
                data.append({"timestamp": time.time(), "cpu_usage": usage})
            time.sleep(interval)
        except Exception:
            continue
    try:
        with open(LOGFILE_PATH, 'w') as logfile:
            json.dump(data, logfile)
        return LOGFILE_PATH
    except IOError:
        return None

